{
  "PROP-01b-partial-pre-007": {
    "property_id": "PROP-01b-partial-pre-007",
    "audit_result": {
      "property_id": "PROP-01b-partial-pre-007",
      "classification": "vulnerability",
      "code_path": "src/sales/LegionPreLiquidApprovedSale.sol::withdrawRaisedCapital::L351-394",
      "proof_trace": "The base class `LegionAbstractSale.withdrawRaisedCapital()` correctly enforces `tokensSupplied == true` via the `whenTokensSupplied` modifier (L203). However, `LegionPreLiquidApprovedSale` overrides this function (L351-394) and omits `whenTokensSupplied` entirely, while the same contract does protect `claimTokenAllocation()` with `whenTokensSupplied` (L409) and provides `supplyTokens()` (L281-296). The override's `_verifyCanWithdrawCapital()` (L973-978) checks only for double-withdrawal, not for token supply, leaving the rug-pull path open.",
      "attack_scenario": "After sale end and the refund period, the project calls `withdrawRaisedCapital()` without ever calling `supplyTokens()`; the call succeeds (`tokensSupplied == false`), transfers all raised capital to the project, and investors are permanently blocked from `claimTokenAllocation()` (which requires `whenTokensSupplied`).",
      "checklist_id": "PROP-01b-partial-pre-007"
    },
    "text": "withdrawRaisedCapital() requires tokensSupplied == true; prevents rug-pull before token delivery.",
    "assertion": "withdrawRaisedCapital() succeeds => tokensSupplied == true",
    "covers": "SG-007",
    "severity": "CRITICAL",
    "type": "pre-condition"
  }
}

